// Little's law: concurrency = throughput (req/s) × latency (s)
// Hardware ceiling (HikariCP starting formula): cores*2 + spindles
function littlesLaw(rps, latencyMs) {
  return rps * (latencyMs / 1000);
}
function hikariCeiling(cores, spindles) {
  return cores * 2 + spindles;
}

const cores = 8, spindles = 1;
const ceiling = hikariCeiling(cores, spindles);

const workloads = [
  { name: 'light',  rps: 200,  latencyMs: 10 },
  { name: 'medium', rps: 1000, latencyMs: 10 },
  { name: 'heavy',  rps: 5000, latencyMs: 10 },
];

console.log('ceiling=' + ceiling);
for (const w of workloads) {
  const needed = littlesLaw(w.rps, w.latencyMs);
  const sized = Math.min(needed, ceiling);
  const bounded = needed > ceiling ? 'hardware-bound' : 'demand-bound';
  console.log(w.name + ': needed=' + needed + ' sized=' + sized + ' ' + bounded);
}
